def max_accordion_length(s):
    stack = []
    max_len = 0
    i = 0
    n = len(s)

    while i < n:
        if s[i] == '[':
            stack.append(i)
        elif s[i] == ']':
            if stack and s[stack[-1]] == '[':
                start = stack.pop()
                if not stack:
                    length = i - start + 1
                    if s[start+1:i].count(':') >= 2:
                        max_len = max(max_len, length)
        i += 1

    return max_len if max_len > 0 else -1

